// Some portions generated by Co-Pilot
"use client";

import { useTranslations } from "next-intl";

interface VersionSelectorProps {
  activeVersionTab: number | string;
  setActiveVersionTab: (tab: number | string) => void;
  versions: Array<{ name: string; value: number }>;
}

const VersionSelector = ({
  activeVersionTab,
  setActiveVersionTab,
  versions,
}: VersionSelectorProps) => {
  const t = useTranslations("Temurin.VersionSelector");
  const tFilters = useTranslations("Temurin.Releases.ReleaseFilters");
  const choices = [
    { name: t("all-versions"), value: 1 },
    ...versions.map((version) => ({ ...version, name: `JDK ${version.name}` })),
  ];
  return (
    <div
      role="group"
      aria-label={tFilters("version")}
      className="flex flex-wrap gap-2"
    >
      {choices.map((version) => (
        <button
          key={version.value}
          type="button"
          data-testid="version-tab"
          aria-pressed={activeVersionTab === version.value}
          onClick={() => setActiveVersionTab(version.value)}
          className={`min-h-11 rounded-xl border px-4 py-2 text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink ${
            activeVersionTab === version.value
              ? "border-pink/50 bg-pink/10 text-[#ff91b7]"
              : "border-transparent text-grey hover:border-white/10 hover:bg-white/5 hover:text-white"
          }`}
        >
          <span>{version.name}</span>
        </button>
      ))}
    </div>
  );
};

export default VersionSelector;
